import 'package:flearn_app/core/constants/colors.dart';
import '../view/login_screen.dart';
import '../viewmodel/login_viewmodel.dart';
import '../viewmodel/user_viewmodel.dart';
import '../../../shared/widgets/app_scaffold.dart';


class ProfileScreen extends StatefulWidget {
  const ProfileScreen({super.key});

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  late final UserViewModel userViewModel;
  final loginViewModel = Get.find<LoginViewModel>();

  @override
  void initState() {
    super.initState();
    if (Get.isRegistered<UserViewModel>()) {
      userViewModel = Get.find<UserViewModel>();
    } else {
      userViewModel = Get.put(UserViewModel(Get.find()), permanent: true);
    }

    WidgetsBinding.instance.addPostFrameCallback((_) {
      _fetchUserProfile();
    });
  }

  Future<void> _fetchUserProfile() async {
    await userViewModel.fetchUserInfo();
  }

  void _navigateToLogin() {
    Get.deleteAll(force: true);
    setupDI();
    Get.offAll(() => const LoginScreen(), transition: Transition.rightToLeftWithFade);
  }

  Future<void> _showLogoutConfirmation() async {
    Get.dialog(
      AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text("Xác nhận đăng xuất"),
        content: const Text("Bạn có chắc chắn muốn đăng xuất không?"),
        actions: [
          TextButton(
            onPressed: () => Get.back(),
            child: const Text("Huỷ"),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () {
              Get.back();
              _logout();
            },
            child: const Text("Đăng xuất"),
          ),
        ],
      ),
    );
  }

  Future<void> _logout() async {
    try {
      final refreshToken = GetStorage().read('refreshToken');
      if (refreshToken != null) {
        await loginViewModel.logoutApi(refreshToken);
      }
      loginViewModel.logout();

      Get.snackbar(
        "Đã đăng xuất",
        "Hẹn gặp lại bạn nhé!",
        snackPosition: SnackPosition.BOTTOM,
        backgroundColor: Colors.black87,
        colorText: Colors.white,
      );

      _navigateToLogin();
    } catch (e) {
      loginViewModel.logout();
      _navigateToLogin();
      debugPrint("Lỗi đăng xuất: $e");
    }
  }

  @override
  Widget build(BuildContext context) {
    return AppScaffold(
      backgroundColor: Colors.white,
      body: RefreshIndicator(
        onRefresh: _fetchUserProfile,
        edgeOffset: 100.0,
        child: SingleChildScrollView(
          physics: const AlwaysScrollableScrollPhysics(),
          child: Column(
            children: [
              _buildHeaderWithAvatar(),
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 2, 16, 24),
                child: _buildFunctionList(),
              ),
              const SizedBox(height: kBottomNavigationBarHeight + 16),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildHeaderWithAvatar() {
    return Obx(() {
      final user = userViewModel.user.value;
      final avatarUrl = user?.avatar;
      final displayName = (user?.fullname != null && user!.fullname!.isNotEmpty)
          ? user.fullname!
          : (user?.username ?? 'Đang tải...');
      final email = user?.email ?? "";

      return Container(
        color: Colors.white,
        child: SafeArea(
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 40),
            child: Column(
              children: [
                // Avatar centered
                GestureDetector(
                  onTap: () => Get.to(
                    () => const EditProfileScreen(),
                    arguments: userViewModel.user.value,
                  ),
                  child: Container(
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withAlpha(25),
                          blurRadius: 15,
                          spreadRadius: 2,
                          offset: const Offset(0, 5),
                        ),
                      ],
                    ),
                    child: CircleAvatar(
                      radius: 60,
                      backgroundColor: Colors.grey.shade100,
                      backgroundImage: (avatarUrl != null && avatarUrl.isNotEmpty)
                          ? NetworkImage(avatarUrl)
                          : null,
                      child: (avatarUrl == null || avatarUrl.isEmpty)
                          ? Icon(
                              CupertinoIcons.person_fill,
                              color: Colors.grey.shade400,
                              size: 50,
                            )
                          : null,
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                // Display Name
                Text(
                  displayName,
                  style: const TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                    color: Colors.black,
                  ),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 4),
                // Email
                Text(
                  email,
                  style: TextStyle(
                    fontSize: 14,
                    color: Colors.grey.shade600,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
      );
    });
  }

  Widget _buildFunctionList() {
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.grey.withAlpha(20),
            blurRadius: 15,
            spreadRadius: 0,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        children: [
          _buildListTile(
            icon: CupertinoIcons.person_circle,
            label: "Chỉnh sửa hồ sơ",
            iconColor: const Color(0xFF4A90E2),
            onTap: () => Get.to(
                  () => const EditProfileScreen(),
              arguments: userViewModel.user.value,
            ),
          ),
          _buildDivider(),
          _buildListTile(
            icon: CupertinoIcons.calendar,
            label: "Lịch học",
            iconColor: const Color(0xFF34C759),
            onTap: () {
              Get.to(
                () => const ScheduleScreen(),
                transition: Transition.cupertino,
              );
            },
          ),
          _buildDivider(),
          _buildListTile(
            icon: CupertinoIcons.doc_text,
            label: "Lịch sử giao dịch",
            iconColor: const Color(0xFF4A90E2),
            onTap: () {
              Get.snackbar(
                'Thông báo',
                'Tính năng đang được phát triển',
                snackPosition: SnackPosition.BOTTOM,
              );
            },
          ),
          _buildDivider(),
          _buildListTile(
            icon: CupertinoIcons.arrow_right_square,
            label: "Đăng xuất",
            iconColor: const Color(0xFFFF3B30),
            onTap: _showLogoutConfirmation,
            showArrow: false,
          ),
        ],
      ),
    );
  }

  Widget _buildDivider() {
    return Padding(
      padding: const EdgeInsets.only(left: 72),
      child: Divider(
        height: 1,
        thickness: 1,
        color: Colors.grey.shade100,
      ),
    );
  }

  Widget _buildListTile({
    required IconData icon,
    required String label,
    required Color iconColor,
    required VoidCallback onTap,
    bool showArrow = true,
  }) {
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(16),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),
          child: Row(
            children: [
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: iconColor.withAlpha(25),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(
                  icon,
                  color: iconColor,
                  size: 24,
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Text(
                  label,
                  style: const TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w500,
                    color: Color(0xFF1A1A1A),
                  ),
                ),
              ),
              if (showArrow)
                Icon(
                  CupertinoIcons.chevron_right,
                  color: Colors.grey.shade400,
                  size: 20,
                ),
            ],
          ),
        ),
      ),
    );
  }
}

// Custom Painter để vẽ đường cong wave
class WavePainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..shader = const LinearGradient(
        colors: [Color(0xFF4A90E2), Color(0xFF5AB0FF)],
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
      ).createShader(Rect.fromLTWH(0, 0, size.width, size.height));

    final path = Path();
    path.lineTo(0, size.height - 60);

    // Vẽ đường cong wave
    path.quadraticBezierTo(
      size.width * 0.25,
      size.height - 20,
      size.width * 0.5,
      size.height - 40,
    );
    path.quadraticBezierTo(
      size.width * 0.75,
      size.height - 60,
      size.width,
      size.height - 20,
    );

    path.lineTo(size.width, 0);
    path.close();

    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flearn_app/core/constants/colors.dart';
import 'package:get/get.dart';
import 'package:get_storage/get_storage.dart';
import 'package:dio/dio.dart';

import '../model/course.dart';
import '../viewmodel/course_viewmodel.dart';
import 'course_detail_screen.dart';

class BrowseCourseScreen extends StatefulWidget {
  final String? searchQuery;
  final String? topic;
  final String? sortBy;
  final String? programId;

  const BrowseCourseScreen({
    super.key,
    this.searchQuery,
    this.topic,
    this.sortBy,
    this.programId,
  });

  @override
  State<BrowseCourseScreen> createState() => _BrowseCourseScreenState();
}

class _BrowseCourseScreenState extends State<BrowseCourseScreen> {
  final CourseViewModel courseViewModel = Get.find<CourseViewModel>();
  final TextEditingController _searchController = TextEditingController();
  final Dio _dio = Dio();

  @override
  void initState() {
    super.initState();
    _searchController.text = widget.searchQuery ?? '';
    _loadCourses();
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<String?> _getCurrentLanguageCode() async {
    try {
      final box = GetStorage();
      final user = box.read('user');

      if (user != null && user['languageId'] != null) {
        final String languageId = user['languageId'];

        // Fetch languages to get langCode
        final response = await _dio.get('https://f-learn.app/api/languages');
        if (response.statusCode == 200 && response.data['status'] == 'success') {
          List<dynamic> languages = response.data['data'];
          final language = languages.firstWhere(
            (lang) => lang['id'] == languageId,
            orElse: () => null,
          );

          if (language != null) {
            return language['langCode'] as String?;
          }
        }
      }
    } catch (e) {
      debugPrint('Error getting language code: $e');
    }
    return null;
  }

  Future<void> _loadCourses() async {
    // Get language code
    final langCode = await _getCurrentLanguageCode();

    debugPrint('BrowseCourseScreen: Loading courses with langCode: $langCode, search: ${widget.searchQuery}, sortBy: ${widget.sortBy}');

    await courseViewModel.fetchCoursesWithLanguage(
      lang: langCode,
      searchTerm: widget.searchQuery,
      sortBy: widget.sortBy,
      isRefresh: true,
    );
  }

  String _getTitle() {
    if (widget.searchQuery != null && widget.searchQuery!.isNotEmpty) {
      return 'Kết quả tìm kiếm';
    }
    if (widget.topic != null) {
      return widget.topic!;
    }
    return 'Khám phá khóa học';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF8F9FA),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        centerTitle: true,
        leading: IconButton(
          icon: const Icon(CupertinoIcons.back, color: Color(0xFF1A1A1A)),
          onPressed: () => Get.back(),
        ),
        title: Text(
          _getTitle(),
          style: const TextStyle(
            color: Color(0xFF1A1A1A),
            fontWeight: FontWeight.w600,
            fontSize: 18,
          ),
        ),
      ),
      body: RefreshIndicator(
        onRefresh: _loadCourses,
        child: SingleChildScrollView(
          physics: const AlwaysScrollableScrollPhysics(),
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Search bar
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.grey.withAlpha(25),
                        blurRadius: 4,
                        offset: const Offset(0, 2),
                      ),
                    ],
                  ),
                  child: TextField(
                    controller: _searchController,
                    onSubmitted: (value) {
                      if (value.isNotEmpty) {
                        Get.off(
                          () => BrowseCourseScreen(
                            searchQuery: value,
                            topic: widget.topic,
                            sortBy: widget.sortBy,
                            programId: widget.programId,
                          ),
                        );
                      }
                    },
                    decoration: const InputDecoration(
                      icon: Icon(CupertinoIcons.search, color: Colors.grey),
                      border: InputBorder.none,
                      hintText: 'Tìm kiếm khóa học...',
                    ),
                  ),
                ),
                const SizedBox(height: 20),

                // Courses list
                Obx(() {
                  if (courseViewModel.isLoadingCourse.value) {
                    return const Center(
                      child: Padding(
                        padding: EdgeInsets.all(50.0),
                        child: CupertinoActivityIndicator(),
                      ),
                    );
                  }

                  var courses = courseViewModel.courses;

                  // Filter by topic if specified
                  if (widget.topic != null && widget.topic!.isNotEmpty) {
                    courses = courses.where((course) {
                      return course.topics.any((topic) => topic.topicName == widget.topic);
                    }).toList().obs;
                  }

                  // Filter by program if specified
                  if (widget.programId != null && widget.programId!.isNotEmpty) {
                    courses = courses.where((course) {
                      return course.program?.programId == widget.programId;
                    }).toList().obs;
                  }

                  if (courses.isEmpty) {
                    return Center(
                      child: Padding(
                        padding: const EdgeInsets.all(50.0),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              Icons.school_outlined,
                              size: 80,
                              color: Colors.grey.shade300,
                            ),
                            const SizedBox(height: 16),
                            Text(
                              'Không tìm thấy khóa học',
                              style: TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                                color: Colors.grey.shade600,
                              ),
                            ),
                            const SizedBox(height: 8),
                            Text(
                              widget.searchQuery != null && widget.searchQuery!.isNotEmpty
                                  ? 'Thử tìm kiếm với từ khóa khác'
                                  : 'Chưa có khóa học nào phù hợp với bộ lọc',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                fontSize: 14,
                                color: Colors.grey.shade500,
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  }

                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Tìm thấy ${courses.length} khóa học',
                        style: TextStyle(
                          fontSize: 14,
                          color: Colors.grey.shade600,
                        ),
                      ),
                      const SizedBox(height: 16),
                      ListView.separated(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        itemCount: courses.length,
                        separatorBuilder: (context, index) => const SizedBox(height: 16),
                        itemBuilder: (context, index) {
                          final course = courses[index];
                          return _CourseCard(course: course);
                        },
                      ),
                    ],
                  );
                }),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _CourseCard extends StatelessWidget {
  final Course course;

  const _CourseCard({required this.course});

  String formatVND(int price) {
    if (price == 0) return 'Miễn phí';
    return '${price.toString().replaceAllMapped(RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))'), (Match m) => '${m[1]}.')}₫';
  }

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: () {
        Get.to(() => CourseDetailScreen(courseId: course.courseID));
      },
      child: Card(
        elevation: 2,
        clipBehavior: Clip.antiAlias,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Stack(
              children: [
                (course.imageUrl.isNotEmpty)
                    ? Image.network(
                        course.imageUrl,
                        width: double.infinity,
                        height: 180,
                        fit: BoxFit.cover,
                      )
                    : Container(
                        width: double.infinity,
                        height: 180,
                        color: Colors.grey.shade200,
                        child: const Icon(Icons.school, color: Colors.grey, size: 60),
                      ),
                Positioned(
                  top: 12,
                  left: 12,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                    decoration: BoxDecoration(
                      color: course.courseType == 'Free'
                          ? Colors.green.shade400
                          : Colors.orange.shade400,
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      formatVND(course.price),
                      style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 14,
                      ),
                    ),
                  ),
                ),
              ],
            ),
            Padding(
              padding: const EdgeInsets.all(16.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: AppColors.primary.withAlpha(25),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text(
                      course.program?.name ?? 'Chương trình',
                      style: const TextStyle(
                        fontSize: 12,
                        color: AppColors.primary,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    course.title,
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 16,
                    ),
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      const Icon(Icons.star, color: Colors.orange, size: 18),
                      const SizedBox(width: 4),
                      Text(
                        '${course.averageRating}',
                        style: const TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(width: 16),
                      Icon(Icons.person_outline, color: Colors.grey.shade600, size: 18),
                      const SizedBox(width: 4),
                      Text(
                        '${course.learnerCount} học viên',
                        style: TextStyle(
                          fontSize: 13,
                          color: Colors.grey.shade600,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flearn_app/core/constants/colors.dart';
import 'package:get/get.dart';
import 'package:get_storage/get_storage.dart';
import 'package:dio/dio.dart';

import '../model/course.dart';
import '../viewmodel/course_viewmodel.dart';
import 'course_detail_screen.dart';

class BrowseCourseScreen extends StatefulWidget {
  final String? searchQuery;
  final String? topic;
  final String? sortBy;
  final String? programId;

  const BrowseCourseScreen({
    super.key,
    this.searchQuery,
    this.topic,
    this.sortBy,
    this.programId,
  });

  @override
  State<BrowseCourseScreen> createState() => _BrowseCourseScreenState();
}

class _BrowseCourseScreenState extends State<BrowseCourseScreen> {
  final CourseViewModel courseViewModel = Get.find<CourseViewModel>();
  final TextEditingController _searchController = TextEditingController();
  final Dio _dio = Dio();

  // Local state to prevent data loss
  final RxList<Course> _localCourses = <Course>[].obs;
  final RxBool _isLoading = false.obs;

  @override
  void initState() {
    super.initState();
    _searchController.text = widget.searchQuery ?? '';
    _loadCourses();
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<String?> _getCurrentLanguageCode() async {
    try {
      final box = GetStorage();
      final user = box.read('user');

      if (user != null && user['languageId'] != null) {
        final String languageId = user['languageId'];

        // Fetch languages to get langCode
        final response = await _dio.get('https://f-learn.app/api/languages');
        if (response.statusCode == 200 && response.data['status'] == 'success') {
          List<dynamic> languages = response.data['data'];
          final language = languages.firstWhere(
            (lang) => lang['id'] == languageId,
            orElse: () => null,
          );

          if (language != null) {
            return language['langCode'] as String?;
          }
        }
      }
    } catch (e) {
      debugPrint('Error getting language code: $e');
    }
    return null;
  }

  Future<void> _loadCourses() async {
    try {
      _isLoading.value = true;

      // Get language code
      final langCode = await _getCurrentLanguageCode();

      debugPrint('BrowseCourseScreen: Loading courses with langCode: $langCode, search: ${widget.searchQuery}, sortBy: ${widget.sortBy}');

      // Fetch courses but store in local state
      await courseViewModel.fetchCoursesWithLanguage(
        lang: langCode,
        searchTerm: widget.searchQuery,
        sortBy: widget.sortBy,
        isRefresh: true,
      );

      // Copy to local state to prevent loss
      _localCourses.value = List.from(courseViewModel.courses);

      debugPrint('BrowseCourseScreen: Loaded ${_localCourses.length} courses');
    } catch (e) {
      debugPrint('BrowseCourseScreen: Error loading courses: $e');
    } finally {
      _isLoading.value = false;
    }
  }

  String _getTitle() {
    if (widget.searchQuery != null && widget.searchQuery!.isNotEmpty) {
      return 'Kết quả tìm kiếm';
    }
    if (widget.topic != null) {
      return widget.topic!;
    }
    return 'Khám phá khóa học';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF8F9FA),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        centerTitle: true,
        leading: IconButton(
          icon: const Icon(CupertinoIcons.back, color: Color(0xFF1A1A1A)),
          onPressed: () => Get.back(),
        ),
        title: Text(
          _getTitle(),
          style: const TextStyle(
            color: Color(0xFF1A1A1A),
            fontWeight: FontWeight.w600,
            fontSize: 18,
          ),
        ),
      ),
      body: RefreshIndicator(
        onRefresh: _loadCourses,
        child: SingleChildScrollView(
          physics: const AlwaysScrollableScrollPhysics(),
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Search bar
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.grey.withAlpha(25),
                        blurRadius: 4,
                        offset: const Offset(0, 2),
                      ),
                    ],
                  ),
                  child: TextField(
                    controller: _searchController,
                    onSubmitted: (value) async {
                      if (value.trim().isNotEmpty) {
                        // Navigate to new search results
                        Get.off(
                          () => BrowseCourseScreen(
                            searchQuery: value.trim(),
                            topic: widget.topic,
                            sortBy: widget.sortBy,
                            programId: widget.programId,
                          ),
                        );
                      } else {
                        // Clear search and reload
                        _searchController.clear();
                        setState(() {});
                        await _loadCourses();
                      }
                    },
                    decoration: InputDecoration(
                      icon: const Icon(CupertinoIcons.search, color: Colors.grey),
                      border: InputBorder.none,
                      hintText: 'Tìm kiếm khóa học...',
                      suffixIcon: _searchController.text.isNotEmpty
                          ? IconButton(
                              icon: const Icon(Icons.clear, size: 20),
                              onPressed: () {
                                _searchController.clear();
                                setState(() {});
                                _loadCourses();
                              },
                            )
                          : null,
                    ),
                    onChanged: (value) {
                      setState(() {}); // Update UI for clear button
                    },
                  ),
                ),
                const SizedBox(height: 20),

                // Courses list
                Obx(() {
                  // Use local loading state
                  if (_isLoading.value) {
                    return const Center(
                      child: Padding(
                        padding: EdgeInsets.all(50.0),
                        child: CupertinoActivityIndicator(),
                      ),
                    );
                  }

                  // Use local courses to prevent data loss
                  var courses = _localCourses;

                  // Filter by topic if specified
                  if (widget.topic != null && widget.topic!.isNotEmpty) {
                    courses = courses.where((course) {
                      return course.topics.any((topic) => topic.topicName == widget.topic);
                    }).toList().obs;
                  }

                  // Filter by program if specified
                  if (widget.programId != null && widget.programId!.isNotEmpty) {
                    courses = courses.where((course) {
                      return course.program?.programId == widget.programId;
                    }).toList().obs;
                  }

                  if (courses.isEmpty) {
                    return Center(
                      child: Padding(
                        padding: const EdgeInsets.all(50.0),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              Icons.school_outlined,
                              size: 80,
                              color: Colors.grey.shade300,
                            ),
                            const SizedBox(height: 16),
                            Text(
                              'Không tìm thấy khóa học',
                              style: TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                                color: Colors.grey.shade600,
                              ),
                            ),
                            const SizedBox(height: 8),
                            Text(
                              widget.searchQuery != null && widget.searchQuery!.isNotEmpty
                                  ? 'Thử tìm kiếm với từ khóa khác'
                                  : 'Chưa có khóa học nào phù hợp với bộ lọc',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                fontSize: 14,
                                color: Colors.grey.shade500,
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  }

                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Tìm thấy ${courses.length} khóa học',
                        style: TextStyle(
                          fontSize: 14,
                          color: Colors.grey.shade600,
                        ),
                      ),
                      const SizedBox(height: 16),
                      ListView.separated(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        itemCount: courses.length,
                        separatorBuilder: (context, index) => const SizedBox(height: 16),
                        itemBuilder: (context, index) {
                          final course = courses[index];
                          return _CourseCard(course: course);
                        },
                      ),
                    ],
                  );
                }),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _CourseCard extends StatelessWidget {
  final Course course;

  const _CourseCard({required this.course});

  String formatVND(int price) {
    if (price == 0) return 'Miễn phí';
    return '${price.toString().replaceAllMapped(RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))'), (Match m) => '${m[1]}.')}₫';
  }

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: () {
        Get.to(() => CourseDetailScreen(courseId: course.courseID));
      },
      child: Card(
        elevation: 2,
        clipBehavior: Clip.antiAlias,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Stack(
              children: [
                (course.imageUrl.isNotEmpty)
                    ? Image.network(
                        course.imageUrl,
                        width: double.infinity,
                        height: 180,
                        fit: BoxFit.cover,
                      )
                    : Container(
                        width: double.infinity,
                        height: 180,
                        color: Colors.grey.shade200,
                        child: const Icon(Icons.school, color: Colors.grey, size: 60),
                      ),
                Positioned(
                  top: 12,
                  left: 12,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                    decoration: BoxDecoration(
                      color: course.courseType == 'Free'
                          ? Colors.green.shade400
                          : Colors.orange.shade400,
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      formatVND(course.price),
                      style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 14,
                      ),
                    ),
                  ),
                ),
              ],
            ),
            Padding(
              padding: const EdgeInsets.all(16.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: AppColors.primary.withAlpha(25),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text(
                      course.program?.name ?? 'Chương trình',
                      style: const TextStyle(
                        fontSize: 12,
                        color: AppColors.primary,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    course.title,
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 16,
                    ),
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      const Icon(Icons.star, color: Colors.orange, size: 18),
                      const SizedBox(width: 4),
                      Text(
                        '${course.averageRating}',
                        style: const TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(width: 16),
                      Icon(Icons.person_outline, color: Colors.grey.shade600, size: 18),
                      const SizedBox(width: 4),
                      Text(
                        '${course.learnerCount} học viên',
                        style: TextStyle(
                          fontSize: 13,
                          color: Colors.grey.shade600,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

class AppScaffold extends StatelessWidget {
  final PreferredSizeWidget? appBar;
  final Widget body;
  final Widget? bottomNavigationBar;
  final Widget? floatingActionButton;
  final Color? backgroundColor;

  const AppScaffold({
    super.key,
    this.appBar,
    required this.body,
    this.bottomNavigationBar,
    this.floatingActionButton,
    this.backgroundColor,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: appBar,
      backgroundColor: backgroundColor,
      resizeToAvoidBottomInset: true,
      body: SafeArea(
        top: false,
        child: body,
      ),
      bottomNavigationBar: bottomNavigationBar,
      floatingActionButton: floatingActionButton,
    );
  }
}

